    // https://leetcode.cn/problems/longest-balanced-substring-ii/description/?envType=daily-question&envId=2026-02-17
    #include <bits/stdc++.h>
    using namespace std;

    typedef long long ll;


    class Solution {
    public:
        int longestBalanced(string s) {
            int n=s.length();
            s.insert(s.begin(), '0');
            vector<int> prefixa(n+1, 0), prefixb(n+1, 0), prefixc(n+1, 0), subfixa(n+2, 0), subfixb(n+2, 0), subfixc(n+2, 0);
            int ans=1,cnt=1;
            for(int i=2;i<=n;i++){
                if(s[i] == s[i-1]) {
                    cnt++;
                } else {
                    cnt=1;
                }
                ans = max(ans, cnt);
            }
            for(int i=1;i<=n;i++) {
                prefixa[i] = prefixa[i-1] + (s[i]=='a');
                prefixb[i] = prefixb[i-1] + (s[i]=='b');
                prefixc[i] = prefixc[i-1] + (s[i]=='c');
            }
            for(int i=n;i>=1;i--) {
                subfixa[i] = subfixa[i+1] + (s[i]=='a');
                subfixb[i] = subfixb[i+1] + (s[i]=='b');
                subfixc[i] = subfixc[i+1] + (s[i]=='c');
            }
            int chaab=prefixa[n]-prefixb[n],cbaac=prefixa[n]-prefixc[n];
            int cnta=prefixa[n], cntb=prefixb[n], cntc=prefixc[n];
            map<pair<int,int>, int> lastpos;
            map<pair<int,int>,int> lastposab, lastposbc, lastposac;
            for(int i=1;i<=n;i++) {
                lastpos[{subfixa[i]-subfixb[i], subfixa[i]-subfixc[i]}] = i;
                lastposab[{subfixa[i]-subfixb[i], subfixc[i]}] = i;
                lastposbc[{subfixb[i]-subfixc[i], subfixa[i]}] = i;
                lastposac[{subfixa[i]-subfixc[i], subfixb[i]}] = i;
            }lastpos[{0, 0}] = n+1;
            lastposab[{0, 0}] = n+1;
            lastposbc[{0, 0}] = n+1;
            lastposac[{0, 0}] = n+1;
            // int ans = 0;
            // if(lastpos.count({chaab, cbaac})) {
            //     ans = max(ans, lastpos[{chaab, cbaac}]-1);
            // }
            for(int i=1;i<=n;i++) {
                int needab=chaab - (prefixa[i-1]-prefixb[i-1]), needac= cbaac - (prefixa[i-1]-prefixc[i-1]), needbc = (cntb-cntc) - (prefixb[i-1]-prefixc[i-1]);
                if(lastpos.count({needab, needac})) {
                    ans = max(ans, lastpos[{needab, needac}]-i);
                }
                if(lastposab.count({needab, cntc-prefixc[i-1]})) {
                    ans = max(ans, lastposab[{needab, cntc-prefixc[i-1]}]-i);
                }
                if(lastposbc.count({needbc, cnta-prefixa[i-1]})) {
                    ans = max(ans, lastposbc[{needbc, cnta-prefixa[i-1]}]-i);
                }
                if(lastposac.count({needac, cntb-prefixb[i-1]})) {
                    ans = max(ans, lastposac[{needac, cntb-prefixb[i-1]}]-i);
                }

            }       
            return ans;


        }
    };



    ll qpow(ll b, ll p, ll mod)
    {
        ll r = 1;
        while (p)
        {
            if (p & 1)
                r = r * b % mod;
            b = b * b % mod, p >>= 1;
        }
        return r;
    }

    int ex_gcd(int a, int b, int &x, int &y)
    {
        if (!b)
        {
            x = 1;
            y = 0;
            return a;
        }
        else
        {
            int d = ex_gcd(b, a % b, y, x);
            y -= a / b * x;
            return d;
        }
    }

    int solve_linear_congruence_equation(int a, int b, int n)
    {
        int x, y;
        int d = ex_gcd(a, n, x, y);
        if (b % d)
            return -1;
        n /= d;
        return ((long long)x * (b / d) % n + n) % n;
    }
                                                                                                                                                                            
                                                                                                                                                            
                                                                                                                                                            
